import{_ as p,V as o,W as l,Z as s,a1 as n,$ as e,X as c,Y as t,F as i}from"./framework-b1bd8911.js";const r={},u=s("strong",null,"发包流程",-1),d={href:"http://issues.sonatype.org",target:"_blank",rel:"noopener noreferrer"},k=s("code",null,"mvn deploy",-1),g={href:"https://central.sonatype.com/",target:"_blank",rel:"noopener noreferrer"},v=s("code",null,"central-publishing-maven-plugin",-1),m=s("strong",null,"git push 即发包，全程无人工",-1),b={href:"https://github.com/liuyueyi/quick-chinese-transfer",target:"_blank",rel:"noopener noreferrer"},h=s("p",null,"对应配置文件：",-1),_={href:"https://github.com/liuyueyi/quick-chinese-transfer/blob/master/pom.xml",target:"_blank",rel:"noopener noreferrer"},f=s("code",null,"release",-1),y={href:"https://github.com/liuyueyi/quick-chinese-transfer/blob/master/.github/workflows/maven-central-publish.yml",target:"_blank",rel:"noopener noreferrer"},P=s("h2",{id:"_1-前置准备",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#_1-前置准备","aria-hidden":"true"},"#"),n(" 1. 前置准备")],-1),x=s("h3",{id:"_1-1-sonatype-central-portal-账号与命名空间",tabindex:"-1"},[s("a",{class:"header-anchor",href:"#_1-1-sonatype-central-portal-账号与命名空间","aria-hidden":"true"},"#"),n(" 1.1 Sonatype Central Portal 账号与命名空间")],-1),G={href:"https://central.sonatype.com/",target:"_blank",rel:"noopener noreferrer"},S={href:"http://issues.sonatype.org",target:"_blank",rel:"noopener noreferrer"},I=t(`<ol><li>注册/登录 Sonatype 账号；</li><li>注册一个 <strong>namespace（groupId）</strong>，比如本项目用的是 <code>com.github.liuyueyi</code>。github 用户可以用 <code>io.github.&lt;用户名&gt;</code> 免验证；</li><li>在账号设置里 <strong>Generate User Token</strong>，得到一对 <code>Token Username</code> / <code>Token Password</code>。</li></ol><blockquote><p>注意：这里用的是 <strong>Token</strong>，不是登录账号密码！后面 Maven 认证用的就是这对 token。</p></blockquote><h3 id="_1-2-gpg-密钥" tabindex="-1"><a class="header-anchor" href="#_1-2-gpg-密钥" aria-hidden="true">#</a> 1.2 GPG 密钥</h3><p>中央仓库要求所有构件（jar、sources、javadoc、pom）必须有 GPG 签名。本地生成并上传公钥：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 生成密钥对（按提示输入姓名、邮箱、passphrase）</span>
gpg --gen-key

<span class="token comment"># 查看密钥 ID</span>
gpg --list-keys

<span class="token comment"># 上传公钥到 keyserver（central portal 校验签名用）</span>
gpg <span class="token parameter variable">--keyserver</span> keyserver.ubuntu.com --send-keys <span class="token operator">&lt;</span>密钥ID<span class="token operator">&gt;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>后面 GitHub Action 里需要两样东西：</p><ul><li><code>GPG_PRIVATE_KEY</code>：私钥的 <strong>ASCII armored 导出内容</strong>（<code>gpg --export-secret-keys --armor &lt;密钥ID&gt;</code> 的输出全文）</li><li><code>GPG_PASSPHRASE</code>：生成密钥时设置的 passphrase</li></ul><h3 id="_1-3-配置-github-secrets" tabindex="-1"><a class="header-anchor" href="#_1-3-配置-github-secrets" aria-hidden="true">#</a> 1.3 配置 GitHub Secrets</h3><p>在 GitHub 仓库的 <code>Settings → Secrets and variables → Actions → New repository secret</code> 中添加 4 个 secret：</p><table><thead><tr><th>Secret 名</th><th>内容</th></tr></thead><tbody><tr><td><code>MAVEN_USERNAME</code></td><td>Central Portal 的 Token Username</td></tr><tr><td><code>MAVEN_PASSWORD</code></td><td>Central Portal 的 Token Password</td></tr><tr><td><code>GPG_PRIVATE_KEY</code></td><td>GPG 私钥（armor 格式全文）</td></tr><tr><td><code>GPG_PASSPHRASE</code></td><td>GPG passphrase</td></tr></tbody></table><h2 id="_2-pom-xml-的发布配置" tabindex="-1"><a class="header-anchor" href="#_2-pom-xml-的发布配置" aria-hidden="true">#</a> 2. pom.xml 的发布配置</h2><h3 id="_2-1-release-profile" tabindex="-1"><a class="header-anchor" href="#_2-1-release-profile" aria-hidden="true">#</a> 2.1 <code>release</code> profile</h3><p>所有发布相关的插件都收在 <code>release</code> profile 里，日常 <code>mvn package</code> 不会触发签名，只在发包时 <code>-P release</code> 激活：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>profiles</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>profile</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>id</span><span class="token punctuation">&gt;</span></span>release<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>id</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>build</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>plugins</span><span class="token punctuation">&gt;</span></span>
                <span class="token comment">&lt;!-- GPG 签名：verify 阶段对全部构件签名 --&gt;</span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>plugin</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>org.apache.maven.plugins<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>maven-gpg-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>1.6<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>executions</span><span class="token punctuation">&gt;</span></span>
                        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>execution</span><span class="token punctuation">&gt;</span></span>
                            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>id</span><span class="token punctuation">&gt;</span></span>sign-artifacts<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>id</span><span class="token punctuation">&gt;</span></span>
                            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>phase</span><span class="token punctuation">&gt;</span></span>verify<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>phase</span><span class="token punctuation">&gt;</span></span>
                            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>goals</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>goal</span><span class="token punctuation">&gt;</span></span>sign<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>goal</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>goals</span><span class="token punctuation">&gt;</span></span>
                        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>execution</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>executions</span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>plugin</span><span class="token punctuation">&gt;</span></span>
                <span class="token comment">&lt;!-- 新版中央仓库发布插件 --&gt;</span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>plugin</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>org.sonatype.central<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>central-publishing-maven-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>0.9.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>extensions</span><span class="token punctuation">&gt;</span></span>true<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>extensions</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>configuration</span><span class="token punctuation">&gt;</span></span>
                        <span class="token comment">&lt;!-- 对应 settings.xml 里 server 的 id --&gt;</span>
                        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>publishingServerId</span><span class="token punctuation">&gt;</span></span>central<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>publishingServerId</span><span class="token punctuation">&gt;</span></span>
                        <span class="token comment">&lt;!-- 上传校验通过后自动发布，无需手动去控制台点 release --&gt;</span>
                        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>autoPublish</span><span class="token punctuation">&gt;</span></span>true<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>autoPublish</span><span class="token punctuation">&gt;</span></span>
                    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>configuration</span><span class="token punctuation">&gt;</span></span>
                <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>plugin</span><span class="token punctuation">&gt;</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>plugins</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>build</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>profile</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>profiles</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>除了这两个插件，中央仓库还要求每个构件附带 sources、javadoc 和必要的 pom 元数据（license、developers、scm），这些在父 pom 的公共构建里已经通过 <code>maven-source-plugin</code>、<code>maven-javadoc-plugin</code> 配好了。</p><h3 id="_2-2-多模块的版本管理" tabindex="-1"><a class="header-anchor" href="#_2-2-多模块的版本管理" aria-hidden="true">#</a> 2.2 多模块的版本管理</h3><p>本项目是 Maven 多模块（<code>transfer-core</code> + <code>hanzi-writer</code>），两个模块<strong>版本号独立演进</strong>：父 pom 固定 <code>0.2</code>，子模块各自带版本（当前 <code>quick-transfer-core:0.2.18</code>、<code>hanzi-writer:0.1.1</code>）。发包时进入对应模块目录执行 <code>mvn deploy</code> 即可只发该模块——这也是后面工作流按分支区分模块的基础。</p><p>发包命令等价于（项目里也留了个 <code>deploy.sh</code>）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 只发 transfer-core</span>
<span class="token builtin class-name">cd</span> transfer-core <span class="token operator">&amp;&amp;</span> mvn clean deploy <span class="token parameter variable">-P</span> release <span class="token parameter variable">-B</span> <span class="token parameter variable">-DskipTests</span>

<span class="token comment"># 全部模块</span>
mvn clean deploy <span class="token parameter variable">-P</span> release <span class="token parameter variable">-B</span> <span class="token parameter variable">-DskipTests</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-github-action-工作流" tabindex="-1"><a class="header-anchor" href="#_3-github-action-工作流" aria-hidden="true">#</a> 3. GitHub Action 工作流</h2><h3 id="_3-1-触发策略-按分支决定发什么" tabindex="-1"><a class="header-anchor" href="#_3-1-触发策略-按分支决定发什么" aria-hidden="true">#</a> 3.1 触发策略：按分支决定发什么</h3><p>因为各模块版本独立，本项目没有用 tag 触发，而是用<strong>三个发布分支</strong>：</p><table><thead><tr><th>分支</th><th>推送后发布的内容</th></tr></thead><tbody><tr><td><code>transfer</code></td><td>只发布 <code>transfer-core</code> 模块</td></tr><tr><td><code>hanzi</code></td><td>只发布 <code>hanzi-writer</code> 模块</td></tr><tr><td><code>release</code></td><td>发布全部模块</td></tr></tbody></table><p>日常开发在 master，当某个模块准备发版时：改版本号 → commit → 把对应分支指向该提交并推送，Action 就会自动发包。工作流定义：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> Publish to Maven Central

<span class="token key atrule">on</span><span class="token punctuation">:</span>
  <span class="token key atrule">push</span><span class="token punctuation">:</span>
    <span class="token key atrule">branches</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> transfer
      <span class="token punctuation">-</span> hanzi
      <span class="token punctuation">-</span> release

<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">publish</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">permissions</span><span class="token punctuation">:</span>
      <span class="token key atrule">contents</span><span class="token punctuation">:</span> read
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Checkout code
        <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4

      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Set up JDK 8
        <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/setup<span class="token punctuation">-</span>java@v4
        <span class="token key atrule">with</span><span class="token punctuation">:</span>
          <span class="token key atrule">java-version</span><span class="token punctuation">:</span> <span class="token string">&#39;8&#39;</span>
          <span class="token key atrule">distribution</span><span class="token punctuation">:</span> <span class="token string">&#39;temurin&#39;</span>

      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Import GPG Key
        <span class="token key atrule">uses</span><span class="token punctuation">:</span> crazy<span class="token punctuation">-</span>max/ghaction<span class="token punctuation">-</span>import<span class="token punctuation">-</span>gpg@v6
        <span class="token key atrule">with</span><span class="token punctuation">:</span>
          <span class="token key atrule">gpg_private_key</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.GPG_PRIVATE_KEY <span class="token punctuation">}</span><span class="token punctuation">}</span>
          <span class="token key atrule">passphrase</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.GPG_PASSPHRASE <span class="token punctuation">}</span><span class="token punctuation">}</span>

      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Create settings.xml
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          mkdir -p ~/.m2
          cat &gt; ~/.m2/settings.xml &lt;&lt; &#39;SETTINGS_EOF&#39;
          ...省略 xml 头...
            &lt;servers&gt;
              &lt;server&gt;
                &lt;id&gt;central&lt;/id&gt;
                &lt;username&gt;\${{ secrets.MAVEN_USERNAME }}&lt;/username&gt;
                &lt;password&gt;\${{ secrets.MAVEN_PASSWORD }}&lt;/password&gt;
              &lt;/server&gt;
            &lt;/servers&gt;
          SETTINGS_EOF</span>

      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build<span class="token punctuation">,</span> Sign and Deploy to Maven Central
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          if [ &quot;\${{ github.ref }}&quot; == &quot;refs/heads/transfer&quot; ]; then
            cd transfer-core &amp;&amp; mvn clean deploy -P release -B -DskipTests
          elif [ &quot;\${{ github.ref }}&quot; == &quot;refs/heads/hanzi&quot; ]; then
            cd hanzi-writer &amp;&amp; mvn clean deploy -P release -B -DskipTests
          elif [ &quot;\${{ github.ref }}&quot; == &quot;refs/heads/release&quot; ]; then
            mvn clean deploy -P release -B -DskipTests
          fi</span>
        <span class="token key atrule">env</span><span class="token punctuation">:</span>
          <span class="token key atrule">GPG_PASSPHRASE</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> secrets.GPG_PASSPHRASE <span class="token punctuation">}</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-几个关键点拆解" tabindex="-1"><a class="header-anchor" href="#_3-2-几个关键点拆解" aria-hidden="true">#</a> 3.2 几个关键点拆解</h3><p><strong>① GPG 私钥导入用 <code>crazy-max/ghaction-import-gpg</code></strong></p><p>不要自己在 CI 里 <code>echo $GPG_PRIVATE_KEY | gpg --import</code>——这个 action 会同时把 passphrase 写进 gpg agent 缓存，让 <code>maven-gpg-plugin</code> 签名时不用人工输密码（本地发包时 gpg 弹窗要密码，CI 里没人输，这就是很多人 CI 签名卡死的原因）。</p><p><strong>② settings.xml 里的 server id 必须是 <code>central</code></strong></p><p><code>central-publishing-maven-plugin</code> 配置的 <code>&lt;publishingServerId&gt;central&lt;/publishingServerId&gt;</code> 会在 deploy 时去 settings.xml 找 id 为 <code>central</code> 的 server 拿认证信息，两边必须对上。</p><p><strong>③ deploy 从子目录执行</strong></p><p><code>cd transfer-core &amp;&amp; mvn deploy</code> 而不是根目录全量 deploy，配合按分支触发的策略，实现&quot;推哪个分支发哪个模块&quot;。</p><p><strong>④ <code>-DskipTests</code></strong></p><p>发包流水线只负责发布，测试放平常的 CI（如 travis/codecov）里跑，避免发包被测试失败阻塞。</p><h2 id="_4-实际发版操作流程" tabindex="-1"><a class="header-anchor" href="#_4-实际发版操作流程" aria-hidden="true">#</a> 4. 实际发版操作流程</h2><p>假设 <code>transfer-core</code> 要从 <code>0.2.18</code> 升到 <code>0.2.19</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 改版本号</span>
<span class="token function">vim</span> transfer-core/pom.xml        <span class="token comment"># 0.2.18 -&gt; 0.2.19</span>
<span class="token function">vim</span> readme.md                    <span class="token comment"># 顺手更新版本说明</span>

<span class="token comment"># 2. 提交</span>
<span class="token function">git</span> <span class="token function">add</span> <span class="token builtin class-name">.</span> <span class="token operator">&amp;&amp;</span> <span class="token function">git</span> commit <span class="token parameter variable">-m</span> <span class="token string">&quot;release 0.2.19&quot;</span>

<span class="token comment"># 3. 把 transfer 分支指向该提交并推送（触发发布）</span>
<span class="token function">git</span> push origin master:transfer
<span class="token comment"># 或者本地切到 transfer 分支合并 master 后 git push origin transfer</span>

<span class="token comment"># 4. 观察 GitHub Actions 日志：build → sign → upload → validation → published</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,37),A={href:"https://central.sonatype.com/",target:"_blank",rel:"noopener noreferrer"},q=s("code",null,"autoPublish=true",-1),E=t('<blockquote><p>常见翻车点速查：</p><ul><li><code>401 Unauthorized</code>：secrets 里填了账号密码而不是 token；</li><li><code>missing signature</code> / gpg 卡住：GPG 私钥没导入或 passphrase 不对；</li><li><code>Invalid publisher</code>：namespace 与 groupId 不匹配（pom 的 groupId 必须是你注册的 namespace）；</li><li>构件校验失败（missing javadoc/sources 等）：确认 <code>maven-source-plugin</code>、<code>maven-javadoc-plugin</code> 已在父 pom 中绑定 <code>package</code> 阶段（本项目已配好，自己改造时别漏）。</li></ul></blockquote><h2 id="_5-小结" tabindex="-1"><a class="header-anchor" href="#_5-小结" aria-hidden="true">#</a> 5. 小结</h2><p>整套自动发包的配置量不大，收益很高：</p><ol><li><strong>pom 侧</strong>：<code>release</code> profile 收纳 gpg 签名 + <code>central-publishing-maven-plugin</code>（<code>autoPublish=true</code>）；</li><li><strong>CI 侧</strong>：4 个 secrets + 一个 40 行的 workflow，按分支决定发布模块；</li><li><strong>发版动作</strong>收敛为&quot;改版本号 → push 发布分支&quot;两步，彻底告别本地 deploy 和手动 staging。</li></ol><p>如果你的开源项目还在手动发包，非常推荐按这个思路改造一遍，一次配置，终身受益。</p>',5);function T(w,C){const a=i("ExternalLinkIcon");return o(),l("div",null,[s("p",null,[n("开源项目发布到 Maven 中央仓库，最麻烦的不是写代码，而是"),u,n("：早期的 OSSRH（"),s("a",d,[n("issues.sonatype.org"),e(a)]),n("）要在本地 "),k,n(" + GPG 签名 + 手动 close/release staging 仓库，一次发包至少十来分钟。Sonatype 迁移到新版中央仓库 "),s("a",g,[n("central.sonatype.com"),e(a)]),n(" 之后，配合 "),v,n(" + GitHub Action，完全可以做到 "),m,n("。")]),s("p",null,[n("这篇教程以 "),s("a",b,[n("quick-chinese-transfer"),e(a)]),n(" 的真实配置为例，完整走一遍这套流程。")]),s("blockquote",null,[h,s("ul",null,[s("li",null,[n("构建发布配置："),s("a",_,[n("pom.xml"),e(a)]),n(" 的 "),f,n(" profile")]),s("li",null,[n("CI 工作流："),s("a",y,[n(".github/workflows/maven-central-publish.yml"),e(a)])])])]),c(" more "),P,x,s("p",null,[n("新版中央仓库的管理入口是 "),s("a",G,[n("central.sonatype.com"),e(a)]),n("（老的 "),s("a",S,[n("issues.sonatype.org"),e(a)]),n(" 工单系统已不再受理新申请）：")]),I,s("p",null,[n("发布成功后，几分钟内即可在 "),s("a",A,[n("central.sonatype.com"),e(a)]),n(" 搜到新版本（"),q,n(" 时无需手动去控制台点 release）。新依赖一般 2~10 分钟同步到中央仓代理（阿里云镜像会慢一些）。")]),E])}const R=p(r,[["render",T],["__file","03.GithubAction自动发布Maven中央仓库.html.vue"]]);export{R as default};
